/** The collapse toggle's chevron: up while the panel is open, down while it is collapsed. */
export function ChevronIcon({ size, direction }: IconProps & { direction: "up" | "down" }) {
  return (
    <svg
      width={size}
      height={size / 2}
      viewBox="0 0 9 4.5"
      fill="none"
      aria-hidden="true"
      style={{
        overflow: "visible",
        transform: direction === "down" ? "rotate(180deg)" : undefined,
      }}
    >
      <path
        d="M 0 4.5 L 4.5 0 L 9 4.5"
        stroke="currentColor"
        strokeWidth={1.5}
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

